<div class="container py-5"><h1>السلة</h1><?php if(!$items): ?><div class="alert alert-info">السلة فارغة.</div><?php else: ?><div class="table-responsive"><table class="table"><thead><tr><th>المنتج</th><th>السعر</th><th>الكمية</th><th>الإجمالي</th><th></th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><?= e($i['product_name']) ?> <?= $i['variant_name']?'— '.e($i['variant_name']):'' ?> <?= $i['weight_grams']?'— '.weight_label($i['weight_grams']):'' ?></td><td><?= money($i['unit_price']) ?></td><td><form method="post" action="<?= url('/cart/update') ?>" class="d-flex gap-2"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $i['id'] ?>"><input class="form-control form-control-sm" style="width:90px" type="number" name="quantity" min="1" value="<?= $i['quantity'] ?>"><button class="btn btn-sm btn-outline-secondary">تحديث</button></form></td><td><?= money($i['unit_price']*$i['quantity']) ?></td><td><form method="post" action="<?= url('/cart/remove') ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $i['id'] ?>"><button class="btn btn-sm btn-outline-danger">حذف</button></form></td></tr><?php endforeach; ?></tbody></table></div><div class="card ms-auto" style="max-width:380px"><div class="card-body"><p>المجموع: <b><?= money($totals['subtotal']) ?></b></p><p>التوصيل: <b><?= money($totals['delivery_fee']) ?></b></p><h4>الإجمالي: <?= money($totals['total']) ?></h4><a class="btn btn-success w-100" href="<?= url('/checkout') ?>">إتمام الطلب</a></div></div><?php endif; ?></div>
